 void downloadChooser(JSONArray links,String title){String[] labels=new String[links.length()];for(int i=0;i<links.length();i++){JSONObject link=links.optJSONObject(i);labels[i]=link.optString("label","دانلود")+(link.optString("size_label").isEmpty()?"":"  •  "+link.optString("size_label"));}new AlertDialog.Builder(this).setTitle("انتخاب نسخه دانلود").setItems(labels,(dialog,index)->{JSONObject link=links.optJSONObject(index);download(link.optString("url"),title,link.optString("quality"));}).setNegativeButton("بستن",null).show();}
 static final class StreamOption{final String url,quality,title,detail;StreamOption(String u,String q,String t,String d){url=u;quality=q;title=t;detail=d;}}
 ArrayList<StreamOption> streamOptions(JSONObject item,String primary){LinkedHashMap<String,StreamOption> found=new LinkedHashMap<>();for(String bucket:new String[]{"stream_links","download_links"}){JSONArray links=item.optJSONArray(bucket);if(links==null)continue;for(int i=0;i<links.length();i++){JSONObject link=links.optJSONObject(i);if(link==null)continue;String url=link.optString("url");if(!isVideoUrl(url)||found.containsKey(url))continue;String quality=qualityLabel(link.optString("quality"),url);String label=link.optString("label");String kind=link.optString("kind");String title=!label.isEmpty()?label:kindLabel(kind);String size=link.optString("size_label");String detail=(kindLabel(kind)+(size.isEmpty()?"":"  •  "+size));found.put(url,new StreamOption(url,quality,title,detail));}}for(String key:new String[]{"video_url","hls_url","signed_playback_url","download_url"})addBareSource(found,item.optString(key),key.equals("hls_url")?"پخش تطبیقی":"پخش آنلاین");JSONObject playback=item.optJSONObject("playback");if(playback!=null){addBareSource(found,playback.optString("signed_playback_url"),"لینک امن پخش");addBareSource(found,playback.optString("hls_url"),"پخش تطبیقی");}addBareSource(found,primary,"پخش پیشنهادی");ArrayList<StreamOption> result=new ArrayList<>(found.values());result.sort((a,b)->Integer.compare(qualityRank(b.quality),qualityRank(a.quality)));if(isVideoUrl(primary))for(int i=0;i<result.size();i++)if(primary.equals(result.get(i).url)){StreamOption preferred=result.remove(i);result.add(0,preferred);break;}return result;}
 void addBareSource(Map<String,StreamOption> found,String url,String title){if(!isVideoUrl(url)||found.containsKey(url))return;found.put(url,new StreamOption(url,qualityLabel("",url),title,url.toLowerCase(Locale.ROOT).contains(".m3u8")?"HLS · تنظیم خودکار":"منبع مستقیم"));}
 String qualityLabel(String raw,String url){String value=(safe(raw)+" "+safe(url)).toLowerCase(Locale.ROOT);if(value.contains("2160")||value.contains("4k"))return "4K";for(String q:new String[]{"1440","1080","720","540","480","360","240"})if(value.contains(q))return q+"p";return value.contains("m3u8")?"AUTO":"HD";}
 int qualityRank(String quality){String q=safe(quality).toLowerCase(Locale.ROOT);if(q.contains("4k"))return 2160;for(String n:new String[]{"1440","1080","720","540","480","360","240"})if(q.contains(n))return Integer.parseInt(n);return 0;}
 String kindLabel(String kind){String k=safe(kind).toLowerCase(Locale.ROOT);if(k.contains("dub"))return "دوبله فارسی";if(k.contains("soft"))return "زیرنویس انتخابی";if(k.contains("hard")||k.contains("sub"))return "زیرنویس فارسی";return "نسخه اصلی";}
 JSONArray itemSources(JSONObject item,String primary){JSONArray out=new JSONArray();for(StreamOption option:streamOptions(item,primary))out.put(option.url);return out;}
